str_enum! {
    /// Label for whatever is currently backing the UI. The sidebar shows this
    /// verbatim so a reviewer can never mistake seeded data for engine output.
    EngineSource {
        RustEngine => "rust-engine",
        DevSeed => "dev-seed",
    }
}

str_enum! {
    /// Queue ordering. Sorting lives in the data layer so that paging stays
    /// correct: page three of an unsorted result set is meaningless.
    JobSort {
        Recent => "recent",
        AmountDesc => "amount_desc",
        ScoreDesc => "score_desc",
        SlaSoonest => "sla_soonest",
    }
}

impl JobSort {
    /// The `ORDER BY` fragment for this sort. Never interpolates user input.
    pub const fn order_by(&self) -> &'static str {
        match self {
            JobSort::Recent => "p.failed_at DESC, j.id DESC",
            JobSort::AmountDesc => "p.amount_paise DESC, j.id DESC",
            JobSort::ScoreDesc => "j.recovery_score DESC, j.id DESC",
            JobSort::SlaSoonest => "j.sla_expires_at ASC, j.id DESC",
        }
    }
}

impl Default for JobSort {
    fn default() -> Self {
        JobSort::Recent
    }
}

