#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CustomerRef {
    pub id: String,
    pub name: String,
    pub email: String,
    /// Masked at the source. The app never holds a full contact number.
    pub phone_masked: String,
    pub lifetime_value_paise: i64,
    pub successful_payments: i64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FailedPayment {
    pub id: String,
    pub razorpay_payment_id: String,
    pub razorpay_order_id: String,
    pub customer: CustomerRef,
    pub amount_paise: i64,
    pub method: PaymentMethod,
    pub card_network: Option<String>,
    pub issuer: Option<String>,
    pub failure_reason: FailureReason,
    /// Verbatim gateway description, shown to humans for ground truth.
    pub gateway_description: String,
    pub failed_at: String,
    pub attempt_count: i64,
    pub is_subscription: bool,
}

/// One weighted input to a score, surfaced verbatim in the UI.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Signal {
    pub label: String,
    /// Contribution to the score, -1..1. Negative signals lower it.
    pub weight: f64,
    pub detail: String,
}

impl Signal {
    pub fn new(label: impl Into<String>, weight: f64, detail: impl Into<String>) -> Self {
        Signal {
            label: label.into(),
            weight,
            detail: detail.into(),
        }
    }
}

