/// A merchant-editable rule set. The engine only ever runs enabled playbooks.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Playbook {
    pub id: String,
    pub name: String,
    pub description: String,
    pub enabled: bool,
    pub trigger: PlaybookTrigger,
    pub steps: Vec<PlaybookStep>,
    pub stats: PlaybookStats,
    pub updated_at: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Actor {
    #[serde(rename = "type")]
    pub kind: ActorType,
    pub name: String,
}

impl Actor {
    pub fn engine() -> Self {
        Actor {
            kind: ActorType::Engine,
            name: "recovery-engine".to_string(),
        }
    }

    pub fn scheduler() -> Self {
        Actor {
            kind: ActorType::System,
            name: "scheduler".to_string(),
        }
    }

    pub fn operator(name: impl Into<String>) -> Self {
        Actor {
            kind: ActorType::User,
            name: name.into(),
        }
    }
}

/// Append-only. Every state change in the system lands here.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AuditEvent {
    pub id: String,
    pub at: String,
    pub actor: Actor,
    /// Dotted machine action, e.g. `job.retry.scheduled`.
    pub action: String,
    /// Human sentence for the same thing.
    pub summary: String,
    pub severity: AuditSeverity,
    pub job_id: Option<String>,
    /// Flat key/value context. `BTreeMap` so the UI renders it in a stable
    /// order rather than whatever the hash seed decided this run.
    pub metadata: BTreeMap<String, String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Merchant {
    pub id: String,
    pub name: String,
    pub mode: MerchantMode,
}

/// Health of the Rust recovery engine, polled by the sidebar.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct EngineStatus {
    pub running: bool,
    pub source: EngineSource,
    pub queue_depth: i64,
    pub last_sweep_at: Option<String>,
    /// Razorpay credentials present and accepted.
    pub razorpay_connected: bool,
}

// ---------------------------------------------------------------------------
// Requests from the UI
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Default, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct QueueFilters {
    #[serde(default)]
    pub statuses: Vec<RecoveryStatus>,
    #[serde(default)]
    pub reasons: Vec<FailureReason>,
    #[serde(default)]
    pub methods: Vec<PaymentMethod>,
    #[serde(default)]
    pub risk_tiers: Vec<RiskTier>,
    /// Matches customer name, email, payment id or order id.
    #[serde(default)]
    pub search: String,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PageRequest {
    pub offset: i64,
    pub limit: i64,
    #[serde(default)]
    pub sort: Option<JobSort>,
}

impl PageRequest {
    /// Clamped so a malformed request cannot ask for the whole table at once.
    pub fn limit(&self) -> i64 {
        self.limit.clamp(1, 500)
    }

    pub fn offset(&self) -> i64 {
        self.offset.max(0)
    }

    pub fn sort(&self) -> JobSort {
        self.sort.unwrap_or_default()
    }
}

/// Mirrors `AuditQuery extends PageRequest` on the TypeScript side. The fields
/// are spelled out rather than flattened so the shape is obvious from here.
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AuditQuery {
    pub offset: i64,
    pub limit: i64,
    #[serde(default)]
    pub severities: Vec<AuditSeverity>,
    #[serde(default)]
    pub search: String,
    #[serde(default)]
    pub job_id: Option<String>,
}

impl AuditQuery {
    pub fn limit(&self) -> i64 {
        self.limit.clamp(1, 1_000)
    }

    pub fn offset(&self) -> i64 {
        self.offset.max(0)
    }
}

/// A page of rows plus the true total, so footers can say "26–50 of 312".
#[derive(Debug, Clone, Serialize)]
pub struct Paged<T> {
    pub rows: Vec<T>,
    pub total: i64,
}

impl<T> Paged<T> {
    pub fn new(rows: Vec<T>, total: i64) -> Self {
        Paged { rows, total }
    }

    pub fn empty() -> Self {
        Paged {
            rows: Vec::new(),
            total: 0,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn enum_json_matches_the_typescript_union() {
        assert_eq!(
            serde_json::to_string(&RecoveryStatus::AwaitingCustomer).unwrap(),
            "\"awaiting_customer\""
        );
        assert_eq!(serde_json::to_string(&Channel::InApp).unwrap(), "\"in_app\"");
        assert_eq!(
            serde_json::to_string(&EngineSource::RustEngine).unwrap(),
            "\"rust-engine\""
        );
    }

    #[test]
    fn enum_storage_name_equals_wire_name() {
        // The whole point of `str_enum!`: one literal drives both.
        for status in RecoveryStatus::ALL {
            let json = serde_json::to_string(status).unwrap();
            assert_eq!(json, format!("\"{}\"", status.as_str()));
            assert_eq!(status.as_str().parse::<RecoveryStatus>().unwrap(), *status);
        }
    }

    #[test]
    fn unknown_enum_values_are_rejected_loudly() {
        assert!("in_flight".parse::<RecoveryStatus>().is_err());
    }

    #[test]
    fn every_status_maps_to_a_funnel_stage() {
        // A status with no stage would silently drop money from the dashboard.
        for status in RecoveryStatus::ALL {
            let stage = status.funnel_stage();
            assert!(FunnelStage::ALL.contains(&stage));
        }
    }

    #[test]
    fn active_statuses_are_never_closed() {
        for status in RecoveryStatus::ACTIVE {
            assert!(!status.is_closed(), "{status} is both active and closed");
        }
    }

    #[test]
    fn camel_case_requests_deserialize() {
        let filters: QueueFilters = serde_json::from_str(
            r#"{"statuses":["queued"],"reasons":[],"methods":["upi"],"riskTiers":["high"],"search":"aarav"}"#,
        )
        .unwrap();
        assert_eq!(filters.statuses, vec![RecoveryStatus::Queued]);
        assert_eq!(filters.methods, vec![PaymentMethod::Upi]);
        assert_eq!(filters.risk_tiers, vec![RiskTier::High]);

        // `sort` is optional on the TypeScript side.
        let page: PageRequest = serde_json::from_str(r#"{"offset":0,"limit":25}"#).unwrap();
        assert_eq!(page.sort(), JobSort::Recent);

        let sorted: PageRequest =
            serde_json::from_str(r#"{"offset":50,"limit":25,"sort":"amount_desc"}"#).unwrap();
        assert_eq!(sorted.sort(), JobSort::AmountDesc);
    }

    #[test]
    fn page_bounds_are_clamped() {
        let hostile: PageRequest =
            serde_json::from_str(r#"{"offset":-40,"limit":9999999}"#).unwrap();
        assert_eq!(hostile.offset(), 0);
        assert_eq!(hostile.limit(), 500);
    }

    #[test]
    fn optional_fields_serialize_as_null_not_missing() {
        // The React types say `string | null`, so the key has to be present.
        let job_id: Option<String> = None;
        let event = AuditEvent {
            id: "evt_1".into(),
            at: "2026-08-22T00:00:00Z".into(),
            actor: Actor::engine(),
            action: "engine.sweep.completed".into(),
            summary: "Queue sweep processed 0 jobs".into(),
            severity: AuditSeverity::Info,
            job_id,
            metadata: BTreeMap::new(),
        };
        let json = serde_json::to_string(&event).unwrap();
        assert!(json.contains("\"jobId\":null"), "{json}");
        assert!(json.contains("\"type\":\"engine\""), "{json}");
    }
}
